import sys
from collections import defaultdict, deque

def bfs_shortest_path(graph, start, end):
    queue = deque([(start, 0)])
    visited = set()
    while queue:
        node, dist = queue.popleft()
        if node == end:
            return dist
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, dist + 1))
    return -1

def find_buses(n, roads, bus_routes, questions):
    tree = defaultdict(list)
    for i, p in enumerate(roads, 2):
        tree[p].append(i)
        tree[i].append(p)

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    def dfs(node, par, d):
        parent[node] = par
        depth[node] = d
        for child in tree[node]:
            if child != par:
                dfs(child, node, d + 1)
    dfs(1, -1, 0)

    def lca(u, v):
        if depth[u] > depth[v]:
            u, v = v, u
        diff = depth[v] - depth[u]
        for _ in range(diff.bit_length()):
            if diff & 1:
                v = parent[v]
            diff >>= 1
        while u != v:
            u, v = parent[u], parent[v]
        return u

    bus_graph = defaultdict(set)
    for a, b in bus_routes:
        anc = lca(a, b)
        path = []
        while a != anc:
            path.append(a)
            a = parent[a]
        path.append(anc)
        while b != anc:
            path.append(b)
            b = parent[b]
        for i in range(len(path)):
            for j in range(i + 1, len(path)):
                bus_graph[path[i]].add(path[j])
                bus_graph[path[j]].add(path[i])

    results = []
    for v, u in questions:
        if v == u:
            results.append(0)
        elif lca(v, u) == 1:
            results.append(-1)
        else:
            dist = bfs_shortest_path(bus_graph, v, u)
            if dist == -1:
                results.append(-1)
            else:
                results.append(dist // 2 + 1)
    return results

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    index += 1
    roads = list(map(int, input[index:index + n - 1]))
    index += n - 1
    m = int(input[index])
    index += 1
    bus_routes = []
    for _ in range(m):
        a = int(input[index])
        b = int(input[index + 1])
        bus_routes.append((a, b))
        index += 2
    q = int(input[index])
    index += 1
    questions = []
    for _ in range(q):
        v = int(input[index])
        u = int(input[index + 1])
        questions.append((v, u))
        index += 2
    results = find_buses(n, roads, bus_routes, questions)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
